 "content": "def transform(grid):
    """Drop each 4-connected colored object toward the solid boundary stripe."""
    h, w = len(grid), len(grid[0])
    boundary = next((r for r, row in enumerate(grid)
                    if row[0] != 0 and all(v == row[0] for v in row)), None)
    if boundary is None:
        return [row[:] for row in grid]
    direction = 1 if boundary == 0 else -1
    fixed = {(boundary, c): grid[boundary][c] for c in range(w)}
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or r == boundary or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x, color))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            objects.append(cells)
    # Settle objects closest to the boundary first, preserving each shape.
    objects.sort(key=lambda obj: min(direction*r for r,_,_ in obj))
    occupied = set(fixed)
    placed = []
    for obj in objects:
        shift = 0
        while True:
            nxt = shift + direction
            if any((r+nxt, c) in occupied or not (0 <= r+nxt < h)
                   for r,c,_ in obj):
                break
            shift = nxt
        moved = [(r+shift, c, color) for r,c,color in obj]
        placed.append(moved)
        occupied.update((r,c) for r,c,_ in moved)
    out = [[0]*w for _ in range(h)]
    for (r,c),color in fixed.items(): out[r][c] = color
    for obj in placed:
        for r,c,color in obj: out[r][c] = color
    return out
